question:
What is a race condition?
int counter = 0;
var t1 = new Thread(() => counter++);
var t2 = new Thread(() => counter++);
t1.Start(); t2.Start();
t1.Join(); t2.Join();
Console.WriteLine(counter);

What does lock() do?
object lockObj = new object();
int counter = 0;
var t1 = new Thread(() => { lock(lockObj) counter++; });
var t2 = new Thread(() => { lock(lockObj) counter++; });
t1.Start(); t2.Start();
t1.Join(); t2.Join();
Console.WriteLine(counter);

What does Thread.Join() do?
var t = new Thread(() => Console.WriteLine("A"));
t.Start();
t.Join();
Console.WriteLine("B");

What does Interlocked.Increment() prevent?
int counter = 0;
var t1 = new Thread(() => Interlocked.Increment(ref counter));
var t2 = new Thread(() => Interlocked.Increment(ref counter));
t1.Start(); t2.Start();
t1.Join(); t2.Join();
Console.WriteLine(counter);

What does ManualResetEvent do?
var resetEvent = new ManualResetEvent(false);
var t = new Thread(() => {
  resetEvent.WaitOne();
  Console.WriteLine("Go");
});
t.Start();
Thread.Sleep(100);
resetEvent.Set();
t.Join();

What is ThreadLocal<T> used for?
var tls = new ThreadLocal<int>(() => 0);
var t1 = new Thread(() => { tls.Value = 1; Console.WriteLine(tls.Value); });
var t2 = new Thread(() => { tls.Value = 2; Console.WriteLine(tls.Value); });
t1.Start(); t2.Start();
t1.Join(); t2.Join();

What does Mutex do?
var mutex = new Mutex();
int counter = 0;
var t1 = new Thread(() => { mutex.WaitOne(); counter++; mutex.ReleaseMutex(); });
var t2 = new Thread(() => { mutex.WaitOne(); counter++; mutex.ReleaseMutex(); });
t1.Start(); t2.Start();
t1.Join(); t2.Join();
Console.WriteLine(counter);

What does Thread.Sleep() do?
var t = new Thread(() => {
  Console.WriteLine("Start");
  Thread.Sleep(100);
  Console.WriteLine("End");
});
t.Start();
t.Join();

What is a deadlock scenario?
object lock1 = new object();
object lock2 = new object();
var t1 = new Thread(() => {
  lock(lock1) { Thread.Sleep(100); lock(lock2) { } }
});
var t2 = new Thread(() => {
  lock(lock2) { Thread.Sleep(100); lock(lock1) { } }
});
t1.Start(); t2.Start();

What does Semaphore do?
var semaphore = new Semaphore(2, 2);
var threads = new Thread[3];
for (int i = 0; i < 3; i++) {
  threads[i] = new Thread(() => {
    semaphore.WaitOne();
    Console.WriteLine("Acquired");
    Thread.Sleep(50);
    semaphore.Release();
  });
  threads[i].Start();
}
